\begin{AlgorithmContract}{
  input={状态数$n$、候选行随机矩阵$A$、候选初始行分布$\rho_0$、有限推进步数$T$与求和容差$\varepsilon$},
  output={最后合法分布、仅含已提交状态的轨迹、完成推进数$t_{\rm done}$、规范化行数$r_{\rm done}$、状态与最终诊断},
  preconditions={$n\ge1,T\in\mathbb N_0,0<\varepsilon<1$；$A$与$\rho_0$维数相容有限；稳定求和与行向量约定已登记},
  initialization={置$t_{\rm done}=r_{\rm done}=0$，逐行验证/规范化$A$，再验证/规范化$\rho_0$并建立单元素轨迹},
  loop={每步由最后合法行分布计算$v=\rho\widehat A$，检查分量域与和，再形成规范化候选},
  update={$\rho^+$通过有限性、$[0,1]$分量域和行和复检后，才原子覆盖$\rho$、追加轨迹并增加$t_{\rm done}$},
  domain={$\widehat A$逐行是概率向量；轨迹中每个$\rho_t$均有限、分量位于$[0,1]$且和为$1$},
  failure={维数、概率域、原始行和或参数非法返回$\mathtt{invalid\_input}$；已通过输入门后的规范化/推进非有限或复检失败返回$\mathtt{numerical\_failure}$并保留上一合法轨迹},
  stop={恰好完成$T$步或首次失败时停止；固定时域完成不宣称渐近收敛},
  budget={恰好至多$T$次分布--矩阵乘法；预处理至多$n$行矩阵规范化和一次初始分布规范化},
  status={$\mathtt{completed}$、$\mathtt{invalid\_input}$、$\mathtt{numerical\_failure}$},
  iterations={$t_{\rm done}$计已原子提交的推进步，$r_{\rm done}$计已通过并提交规范化的矩阵行；失败候选步不计入},
  diagnostics={失败阶段与行/步/分量、原始和及缩放因子、最终概率不变量、实际/计划步数以及链的可约/周期结构提示},
  complexity={稠密校验$\Theta(n^2)$且推进$\Theta(Tn^2)$；稀疏形式为$\Theta((T+1)s)$；轨迹空间$\Theta((T+1)n)$}
}

\index{接受--拒绝抽样}
设$p$与$q$是关于同一支配测度$\nu$的归一化密度；连续情形可取Lebesgue测度，离散情形可取计数测度。记$p\ll q$表示$q(x)=0$时$p(x)=0$对$\nu$几乎处处。假设存在有限常数
\begin{equation}\label{eq:V5-C02-envelope}
c\ge\operatorname*{ess\,sup}_{q(x)>0}\frac{p(x)}{q(x)},
\qquad p(x)\le c q(x)\quad\text{几乎处处}.
\end{equation}
由两边积分可知$c\ge1$。抽取$Y\sim q$和独立的$U\sim\mathrm U(0,1)$，并在
\begin{equation}\label{eq:V5-C02-accept-event}
U\le\alpha(Y),\qquad \alpha(y)=\frac{p(y)}{c q(y)}
\end{equation}
时接受$Y$。在$q=0$的零概率区域可把$\alpha$定义为$0$；使用前仍需验证全局支配条件，不能靠恰好没抽到缺口来证明合法。

\index{重要性抽样}
以下$p,q$仍表示关于同一支配测度$\nu$的密度。设目标量为$I=E_p[h(X)]$，但只能从$q$抽样。要求$p\ll q$，并在$q>0$处定义$w(x)=p(x)/q(x)$。若$Y_i\stackrel{\mathrm{iid}}{\sim}q$，普通重要性估计为
\begin{equation}\label{eq:V5-C02-ordinary-is}
\widehat I_N^{\mathrm{IS}}=\frac1N\sum_{i=1}^Nw(Y_i)h(Y_i).
\end{equation}
这不是“从$p$抽样后不加权”，而是从$q$抽样后用密度比改变量的贡献。

若只能计算未归一化密度$\widetilde p=Zp$且归一化常数$Z>0$未知，令$\widetilde w=\widetilde p/q$，自归一化估计为
\begin{equation}\label{eq:V5-C02-snis}
\widehat I_N^{\mathrm{SNIS}}
=\frac{\sum_{i=1}^N\widetilde w(Y_i)h(Y_i)}
{\sum_{i=1}^N\widetilde w(Y_i)}.
\end{equation}
分母必须为有限正数。自归一化形式消去了未知$Z$，但有限样本下一般有偏；不能把普通重要性抽样的无偏性移植给它。

\phantomsection\label{struct:V5-C03-CH06}
设目标是计算
\begin{equation}\label{eq:V5-C03-target-expectation}
I=E_\pi[f(X)]=\int_{\mathcal X}f(x)\pi(x)\,\mu(\mathrm dx),
\end{equation}
但不能直接产生独立的$\pi$样本。MCMC不把相关状态误称为独立样本，而是设计一个转移核$K$，使$\pi$保持不变，再以同一条链的时间平均
\begin{equation}\label{eq:V5-C03-ergodic-average}
\widehat I_{m,n}
=\frac1n\sum_{t=m+1}^{m+n}f(X_t),\qquad n\ge1,
\end{equation}
估计式\eqref{eq:V5-C03-target-expectation}。式中$m$不是证明链已经收敛的参数；丢弃前$m$步只能减弱某些初值影响，不能修复可约、周期、错误目标或错误转移核。

图\ref{fig:V5-C03-markov-chain-path}区分状态轨迹、提议与拒绝后重复的状态；图\ref{fig:V5-C03-mcmc-pipeline}显示从目标到估计量的完整链路。重复状态是MH核的组成部分，不应在保存轨迹时删除。
